-- 건강검진 내역 조회용 테이블 + 시연용 데이터. MySQL Workbench에서 한 번만 실행
USE gene_insurance;

-- 건보공단 마이데이터를 대신하는 테이블.
-- 본인 확인 값(이름, 생년월일, 성별, 휴대폰)으로 조회한다. 주민등록번호는 저장하지 않는다
-- 검사 항목이 회차·기관마다 달라서, 검진 결과는 JSON 한 칸(result)에 통째로 넣는다
CREATE TABLE health_checkups (
    id           INT AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(50)  NOT NULL,
    birth_date   DATE         NOT NULL,
    gender       CHAR(1)      NOT NULL,               -- M / F
    phone        VARCHAR(11)  NOT NULL,               -- 숫자만 (01012341234)
    checkup_date DATE         NOT NULL,
    hospital     VARCHAR(100) NOT NULL,
    result       JSON         NOT NULL,               -- overall, findings, sections, interview
    created_at   DATETIME     DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_health_checkups_person (name, birth_date, gender, phone)
);

